/**
 * Types of the vendored Promptbook App platform bundle (`app-platform.js`, generated by
 * `scripts/vendor-app-platform.mjs`). Only the surface the engine uses is declared; the platform's contract packages
 * are the reference for every name (webgptorg/app `packages/*`).
 *
 * @private vendored App platform contract
 */

/** A zod schema as the engine uses it: strict parsing with a typed result. */
export type ContractSchema<T = unknown> = {
    readonly safeParse: (value: unknown) => { readonly success: true; readonly data: T } | { readonly success: false; readonly error: { readonly issues: readonly { readonly path: readonly PropertyKey[]; readonly message: string }[] } };
    readonly parse: (value: unknown) => T;
};

/** One engine API operation (`RouteDefinition` of `@ptbk/engine-api`). */
export type ContractRoute = {
    readonly id: string;
    readonly method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
    readonly path: `/${string}`;
    readonly summary: string;
    readonly permission: string | null;
    readonly capability?: { readonly id: string; readonly version: number };
    readonly params?: ContractSchema;
    readonly query?: ContractSchema;
    readonly body?: { readonly kind: 'json' | 'multipart'; readonly schema: ContractSchema };
    readonly responses: Readonly<Partial<Record<200 | 201 | 202 | 204, { readonly kind: 'json'; readonly schema: ContractSchema } | { readonly kind: 'empty' } | { readonly kind: 'sse'; readonly event: ContractSchema } | { readonly kind: 'binary' }>>>;
    readonly problems?: readonly string[];
    readonly stepUp?: true;
    readonly draft?: true;
};

/** RFC 9457 problem details as the contract defines them. */
export type ContractProblem = {
    readonly type: string;
    readonly title: string;
    readonly status: number;
    readonly code: string;
    readonly detail?: string;
    readonly [extension: string]: unknown;
};

/** What an engine API transport answers. */
export type ContractResponse<T = unknown> = { readonly kind: 'ok'; readonly data: T } | { readonly kind: 'problem'; readonly problem: ContractProblem };

/** One parsed request the HTTP binding hands to the transport. */
export type ContractTransportRequest = {
    readonly params?: Readonly<Record<string, string>>;
    readonly query?: Readonly<Record<string, string>>;
    readonly body?: unknown;
    readonly lastEventId?: string;
};

/** The engine API transport port (`EngineApiTransport`). */
export type ContractTransport = (route: ContractRoute, request: ContractTransportRequest, signal: AbortSignal) => Promise<ContractResponse>;

/** `@ptbk/engine-api` as the engine uses it. */
export declare const api: {
    readonly ENGINE_API_VERSION: string;
    readonly ENGINE_API_PREFIX: string;
    readonly ENGINE_UI_CSP: string;
    readonly SIGN_IN_PATH: string;
    readonly SIGN_OUT_PATH: string;
    readonly STEP_UP_PATH: string;
    readonly SETUP_PATH?: string;
    readonly ENGINE_RESERVED_PATHS: readonly string[];
    readonly ENGINE_API_ROUTE_LIST: readonly ContractRoute[];
    readonly ENGINE_API_ROUTES: Readonly<Record<string, ContractRoute>>;
    readonly PERMISSIONS: readonly string[];
    readonly PROBLEM_CODES: readonly string[];
    readonly AUDIT_ACTIONS: readonly string[];
    readonly createProblem: (code: string, extensions?: Readonly<Record<string, unknown>>) => ContractProblem;
    readonly encodeSseMessage: (message: { readonly event?: string; readonly data: string; readonly id?: string }) => string;
    readonly [name: string]: unknown;
};

/** `createEngineApiHttpHandler` of `@ptbk/engine-api/http`. */
export declare function createEngineApiHttpHandler(transport: ContractTransport): (request: Request) => Promise<Response>;

/** `serveEngineApiRoute` of `@ptbk/engine-api/http`. */
export declare function serveEngineApiRoute(transport: ContractTransport, route: ContractRoute, params: Readonly<Record<string, string>>, request: Request): Promise<Response>;

/** A final or partial ClientHello parse (`ClientHelloParse`). */
export type ClientHelloParse =
    | { readonly kind: 'need-more' }
    | { readonly kind: 'sni'; readonly hostname: string; readonly alpn: readonly string[] }
    | { readonly kind: 'no-sni'; readonly alpn: readonly string[] }
    | { readonly kind: 'malformed'; readonly reason: string }
    | { readonly kind: 'too-large' };

/** Why a link URL was refused (`LinkUrlProblem`); never the URL or the code, which is a secret. */
export type LinkUrlProblem = 'not-a-url' | 'not-https' | 'credentials' | 'not-link-path' | 'query' | 'invalid-code';

/** `@ptbk/protocol` as the engine uses it. */
export declare const protocol: {
    readonly createClientHelloBuffer: (limits: { readonly maxBytes: number; readonly maxChunks?: number }) => { push(chunk: Uint8Array): ClientHelloParse; bytes(): Uint8Array };
    /** What `connect --link` accepts: a link URL `https://<dashboard host>/link#<code>`, or a bare code (`dashboardOrigin: null`). */
    readonly parseLinkArgument: (text: string) => { readonly kind: 'ok'; readonly dashboardOrigin: string | null; readonly linkCode: string } | { readonly kind: 'invalid'; readonly problem: LinkUrlProblem };
    readonly [name: string]: unknown;
};

/** `@ptbk/release-tools` as the engine uses it. */
export declare const releaseTools: {
    readonly [name: string]: unknown;
};

/** Gateway page file names and content types (`GATEWAY_ASSETS`). */
export declare const GATEWAY_ASSETS: Readonly<Record<string, string>>;

/** Where the gateway assets are served (`GATEWAY_ASSET_PATH`). */
export declare const GATEWAY_ASSET_PATH: string;

/** Gateway page templates by name (`GATEWAY_PAGES`). */
export declare const GATEWAY_PAGES: Readonly<Record<string, string>>;

/** SHA-256 of the vendored SimpleWebAuthn browser script. */
export declare const SIMPLEWEBAUTHN_BROWSER_SHA256: string;

/** `pickGatewayLanguage(Accept-Language)` of `@ptbk/gateway-pages`. */
export declare function pickGatewayLanguage(acceptLanguage: string | null | undefined): 'en' | 'cs';

/** `renderGatewayPage(template, values)` of `@ptbk/gateway-pages`. */
export declare function renderGatewayPage(template: string, values: Readonly<Record<string, string>>): string;

/** `isSafeNextPath(path)` of `@ptbk/gateway-pages`. */
export declare function isSafeNextPath(path: unknown): boolean;

/** `@simplewebauthn/server` as the engine uses it (options and responses are WebAuthn JSON). */
export declare const webauthn: {
    readonly generateRegistrationOptions: (options: Readonly<Record<string, unknown>>) => Promise<Record<string, unknown> & { readonly challenge: string }>;
    readonly verifyRegistrationResponse: (options: Readonly<Record<string, unknown>>) => Promise<{ readonly verified: boolean; readonly registrationInfo?: { readonly credential: { readonly id: string; readonly publicKey: Uint8Array; readonly counter: number; readonly transports?: readonly string[] }; readonly credentialDeviceType: string; readonly credentialBackedUp: boolean; readonly aaguid: string } }>;
    readonly generateAuthenticationOptions: (options: Readonly<Record<string, unknown>>) => Promise<Record<string, unknown> & { readonly challenge: string }>;
    readonly verifyAuthenticationResponse: (options: Readonly<Record<string, unknown>>) => Promise<{ readonly verified: boolean; readonly authenticationInfo: { readonly credentialID: string; readonly newCounter: number; readonly userVerified: boolean } }>;
};

/** An X.509 certificate of `@peculiar/x509`. */
export type X509Certificate = {
    readonly notBefore: Date;
    readonly notAfter: Date;
    readonly publicKey: unknown;
    toString(format: 'pem' | 'base64'): string;
    readonly rawData: ArrayBuffer;
};

/** An X.509 extension of `@peculiar/x509`. */
export type X509Extension = { readonly type: string; readonly critical: boolean; readonly rawData: ArrayBuffer };

/** `@peculiar/x509` as the engine uses it. */
export declare const x509: {
    readonly X509Certificate: new (raw: string | BufferSource) => X509Certificate;
    readonly X509CertificateGenerator: {
        createSelfSigned(params: { readonly serialNumber?: string; readonly name: string; readonly notBefore: Date; readonly notAfter: Date; readonly keys: CryptoKeyPair; readonly signingAlgorithm: Algorithm | EcdsaParams; readonly extensions?: readonly X509Extension[] }): Promise<X509Certificate>;
        create(params: { readonly serialNumber?: string; readonly subject: string; readonly issuer: string; readonly notBefore: Date; readonly notAfter: Date; readonly publicKey: CryptoKey; readonly signingKey: CryptoKey; readonly signingAlgorithm: Algorithm | EcdsaParams; readonly extensions?: readonly X509Extension[] }): Promise<X509Certificate>;
    };
    readonly Pkcs10CertificateRequestGenerator: {
        create(params: { readonly name?: string; readonly keys: CryptoKeyPair; readonly signingAlgorithm: Algorithm | EcdsaParams; readonly extensions?: readonly X509Extension[] }): Promise<{ readonly rawData: ArrayBuffer }>;
    };
    readonly Extension: new (type: string, critical: boolean, value: BufferSource) => X509Extension;
    readonly BasicConstraintsExtension: new (ca: boolean, pathLength?: number, critical?: boolean) => X509Extension;
    readonly KeyUsagesExtension: new (usages: number, critical?: boolean) => X509Extension;
    readonly KeyUsageFlags: { readonly digitalSignature: number; readonly keyCertSign: number; readonly cRLSign: number };
    readonly ExtendedKeyUsageExtension: new (usages: readonly string[], critical?: boolean) => X509Extension;
    readonly SubjectAlternativeNameExtension: new (names: readonly { readonly type: 'dns' | 'ip'; readonly value: string }[], critical?: boolean) => X509Extension;
    readonly SubjectKeyIdentifierExtension: { create(publicKey: CryptoKey): Promise<X509Extension> };
    readonly AuthorityKeyIdentifierExtension: { create(publicKey: CryptoKey): Promise<X509Extension> };
};
